import java.util.Arrays;
import java.util.Locale;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int T = sc.nextInt();
        int N = sc.nextInt();

        int[] x = new int[N];
        for (int i = 0; i < N; i++) {
            x[i] = sc.nextInt();
        }

        Arrays.sort(x);

        double min = Double.POSITIVE_INFINITY;

        double first = (x[0] + x[1]) / 2.0;
        if (first < min) min = first;

        for (int i = 1; i < N - 1; i++) {
            double len = (x[i + 1] - x[i - 1]) / 2.0;
            if (len < min) min = len;
        }

        double last = (2.0 * T - x[N - 2] - x[N - 1]) / 2.0;
        if (last < min) min = last;

        System.out.printf(Locale.US, "%.2f%n", min);
    }
}
```

